def process(rainfall_amherst, rainfall_boston, rainfall_ashburnham, rainfall_chatham) -> pd.DataFrame:
    cities = {
        'Amherst': rainfall_amherst,
        'Boston': rainfall_boston,
        'Ashburnham': rainfall_ashburnham,
        'Chatham': rainfall_chatham
    }

    results = []
    for city, df in cities.items():
        row_2015 = df[df['Year'] == '2015']
        if len(row_2015) > 0:
            jun = pd.to_numeric(row_2015['Jun'].iloc[0], errors='coerce')
            jul = pd.to_numeric(row_2015['Jul'].iloc[0], errors='coerce')
            aug = pd.to_numeric(row_2015['Aug'].iloc[0], errors='coerce')
            summer_total = sum([x for x in [jun, jul, aug] if pd.notna(x)])
            results.append({'City': city, 'Summer_Rainfall': summer_total})

    return pd.DataFrame(results)

