def process(chatham_beaches):
    pollution_by_beach = chatham_beaches.groupby('Beach Name').agg({
        'Indicator Level': ['mean', 'sum', 'count'],
        'Violation': lambda x: (x == 'yes').sum()
    }).reset_index()

    pollution_by_beach.columns = ['Beach Name', 'Avg_Indicator', 'Total_Indicator', 'Sample_Count', 'Violations']
    pollution_by_beach['Pollution_Score'] = pollution_by_beach['Total_Indicator'] + (pollution_by_beach['Violations'] * 100)
    pollution_by_beach = pollution_by_beach.sort_values('Pollution_Score', ascending=False)

    return pollution_by_beach

